import hashlib
import json
import os
import re
import subprocess
import sys
import time
from datetime import datetime, timedelta
from pathlib import Path

CORE_DATA_EPOCH = 978307200


def env(key, default=""):
    return os.environ.get(key, default)


def param(key, default=""):
    return env("NOTCH_PARAM_" + key.upper(), default)


def fail(msg):
    print(msg, file=sys.stderr)
    sys.exit(1)


def ui_mode():
    raw = param("ui", "list").strip()
    if raw in ("dialog", "弹窗", "button", "picker"):
        return "dialog"
    return "list"


def current_clipboard():
    try:
        raw = subprocess.run(["pbpaste"], capture_output=True, timeout=3).stdout
    except Exception:
        return ""
    if not raw or b"\x00" in raw[:2048]:
        return ""
    text = raw.decode("utf-8", "replace").replace("\r\n", "\n").replace("\r", "\n")
    return text if text.strip() else ""


def detect_ext(text, forced):
    if forced and forced != "auto":
        return forced
    s = text.strip()
    if not s:
        return "txt"
    if s[0] in "{[" and s[-1] in "}]":
        try:
            json.loads(s)
            return "json"
        except Exception:
            pass
    head = s[:5000]
    low = head.lower()
    html_hint = low.startswith("<!doctype html") or low.startswith("<html")
    html_hint = html_hint or bool(
        re.search(r"<(html|head|body|div|span|p|table|article|section)\b", head, re.I)
    )
    if html_hint and re.search(r"</[a-zA-Z][^>]*>", head):
        return "html"
    xml_like = s.startswith("<?xml") or re.match(
        r"<[A-Za-z][\w:.-]*(\s[^>]*)?>[\s\S]*</[A-Za-z]", s
    )
    if xml_like and "html" not in low[:300]:
        return "xml"
    lines = [ln for ln in s.splitlines() if ln.strip()]
    if len(lines) >= 3:
        counts = [ln.count(",") for ln in lines[:30] if ln.count(",") >= 1]
        if len(counts) >= 3 and len(set(counts)) == 1:
            return "csv"
    score = 0
    if re.search(r"^#{1,6}\s+\S", s, re.M):
        score += 2
    if "```" in s:
        score += 2
    if re.search(r"\[[^\]]+\]\([^)]+\)", s):
        score += 1
    if re.search(r"^[-*+]\s+\S", s, re.M):
        score += 1
    if re.search(r"^\d+\.\s+\S", s, re.M):
        score += 1
    if re.search(r"^>\s+\S", s, re.M):
        score += 1
    if re.search(r"^\|.+\|", s, re.M):
        score += 1
    if re.search(r"\*\*[^*\n]+\*\*", s):
        score += 1
    if score >= 2:
        return "md"
    return "txt"


def sanitize_name(name):
    name = re.sub(r"[\\/:*?\"<>|{}[\]()\x00-\x1f]", "_", name)
    name = name.strip(" ._")
    name = re.sub(r"\s+", " ", name)
    name = re.sub(r"_+", "_", name)
    return name[:60] if name else ""


def looks_like_title(line):
    s = line.strip()
    if not s or len(s) > 80:
        return False
    if s[0] in "{[<":
        return False
    if s.startswith("http://") or s.startswith("https://"):
        return False
    return True


def suggested_name(text, mode, ext):
    stamp = datetime.now().strftime("clipboard-%Y%m%d-%H%M%S")
    if mode == "timestamp" or ext in ("json", "html", "xml", "csv"):
        return stamp
    m = re.search(r"^#{1,6}\s+(\S.+)$", text, re.M)
    if m:
        base = sanitize_name(m.group(1))
        if base:
            return base
    for ln in text.splitlines():
        ln = ln.strip().lstrip("#").strip()
        if looks_like_title(ln):
            base = sanitize_name(ln)
            if base:
                return base
    return stamp


def unique_path(folder, base, ext):
    path = folder / f"{base}.{ext}"
    n = 2
    while path.exists():
        path = folder / f"{base}-{n}.{ext}"
        n += 1
    return path


def preview_text(text):
    one = re.sub(r"\s+", " ", text.strip())[:48]
    if len(text.strip()) > 48:
        one = one.rstrip() + "…"
    return one


def item_id(text):
    return hashlib.sha1(text.encode("utf-8", "replace")).hexdigest()[:16]


def read_pastepal(limit):
    db = os.path.expanduser(
        "~/Library/Containers/com.onmyway133.PastePal/Data/Library/Application Support/PastePal/PastePal2.sqlite"
    )
    if not os.path.isfile(db):
        return []
    n = max(1, int(limit))
    query = (
        "SELECT ZSTRING, ZCREATEDAT FROM ZCDCLIPBOARDITEM "
        "WHERE ZSTRING IS NOT NULL AND length(ZSTRING) > 0 "
        "AND IFNULL(ZMARKEDDELETE, 0) = 0 "
        "AND ZITEMTYPE IN ('Text', 'Rich Text', 'Link', 'Email', 'Other') "
        "ORDER BY ZCREATEDAT DESC "
        f"LIMIT {n}"
    )
    try:
        r = subprocess.run(
            ["/usr/bin/sqlite3", "-readonly", "-json", db, query],
            capture_output=True,
            text=True,
            timeout=2,
        )
    except (subprocess.TimeoutExpired, OSError):
        return []
    if r.returncode != 0 or not (r.stdout or "").strip():
        return []
    try:
        rows = json.loads(r.stdout)
    except json.JSONDecodeError:
        return []
    out = []
    if not isinstance(rows, list):
        return []
    for row in rows:
        if not isinstance(row, dict):
            continue
        val = row.get("ZSTRING")
        if isinstance(val, str) and val.strip():
            try:
                ts = int(float(row.get("ZCREATEDAT") or 0) + CORE_DATA_EPOCH)
            except (TypeError, ValueError):
                ts = int(time.time())
            out.append((val.replace("\r\n", "\n").replace("\r", "\n"), ts))
    return out


def collect_history(limit):
    items = []
    seen = set()

    def add(text, ts):
        key = text.strip()
        if not key or key in seen:
            return
        seen.add(key)
        items.append((text, int(ts) if ts else int(time.time())))

    for text, ts in read_pastepal(max(limit * 3, limit)):
        add(text, ts)
        if len(items) >= limit:
            break
    clip = current_clipboard()
    key = clip.strip()
    if key:
        for i, (text, ts) in enumerate(items):
            if text.strip() == key:
                items.insert(0, items.pop(i))
                break
        else:
            items.insert(0, (clip, int(time.time())))
    return items[:limit]


def history_limit():
    try:
        limit = int(float(param("history_n", "12") or "12"))
    except ValueError:
        limit = 12
    return max(3, min(limit, 30))


def forced_format():
    return param("format", "auto").strip().lower() or "auto"


def cache_path():
    folder = Path.home() / "Library/Caches/notchany.clipboard-save"
    folder.mkdir(parents=True, exist_ok=True)
    return folder / "items.json"


def write_cache(records):
    payload = [
        {"id": r["id"], "text": r["text"], "ext": r["ext"], "ts": r.get("ts") or 0}
        for r in records
    ]
    cache_path().write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")


def read_cache():
    path = cache_path()
    if not path.is_file():
        return []
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return []
    if not isinstance(data, list):
        return []
    out = []
    for row in data:
        if not isinstance(row, dict):
            continue
        text = row.get("text")
        ident = row.get("id")
        if isinstance(text, str) and text.strip() and isinstance(ident, str):
            try:
                ts = int(row.get("ts") or 0)
            except (TypeError, ValueError):
                ts = 0
            out.append(
                {
                    "id": ident,
                    "text": text,
                    "ext": row.get("ext") if isinstance(row.get("ext"), str) else "txt",
                    "ts": ts,
                }
            )
    return out


def build_records():
    forced = forced_format()
    limit = history_limit()
    seen = set()
    records = []

    def add(text, ts=0):
        if not isinstance(text, str) or not text.strip():
            return
        ident = item_id(text)
        if ident in seen:
            return
        seen.add(ident)
        records.append(
            {
                "id": ident,
                "text": text,
                "ext": detect_ext(text, forced),
                "ts": int(ts) if ts else int(time.time()),
            }
        )

    for text, ts in collect_history(limit):
        add(text, ts)
    for row in read_cache():
        add(row.get("text"), row.get("ts") or 0)
        if len(records) >= limit:
            break
    records = records[:limit]
    write_cache(records)
    return records


def format_when(ts):
    try:
        ts = int(ts or 0)
    except (TypeError, ValueError):
        return ""
    if ts <= 0:
        return ""
    now = datetime.now()
    try:
        local = datetime.fromtimestamp(ts)
    except (OverflowError, OSError, ValueError):
        return ""
    delta = now - local
    if delta < timedelta(seconds=45):
        return notch_t("just_now")
    if delta < timedelta(hours=1):
        return notch_t("minutes_ago").format(n=max(1, int(delta.total_seconds() // 60)))
    if local.date() == now.date():
        return local.strftime("%H:%M")
    if local.date() == (now.date() - timedelta(days=1)):
        return notch_t("yesterday") + " " + local.strftime("%H:%M")
    if local.year == now.year:
        return notch_t("date_md").format(m=local.month, d=local.day)
    return f"{local.year}/{local.month}/{local.day}"


def widget_state(records, saved=None, message=None):
    items = [
        {
            "id": r["id"],
            "ext": r["ext"],
            "preview": preview_text(r["text"]),
            "chars": len(r["text"]),
            "when": format_when(r.get("ts")),
        }
        for r in records
    ]
    return {
        "ui": ui_mode(),
        "items": items,
        "latest": items[0] if items else None,
        "count": len(items),
        "empty": not items,
        "saved": saved,
        "message": message,
    }


def apple_escape(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')


def choose_item(labels):
    items = ", ".join('"' + apple_escape(x) + '"' for x in labels)
    script = (
        "set theList to {" + items + "}\n"
        'set chosen to choose from list theList with prompt "' + apple_escape(notch_t("pick_prompt")) + '" '
        'OK button name "' + apple_escape(notch_t("ok")) + '" cancel button name "' + apple_escape(notch_t("cancel")) + '" default items {item 1 of theList}\n'
        "if chosen is false then\n"
        '    return "__CANCEL__"\n'
        "end if\n"
        "return item 1 of chosen\n"
    )
    try:
        r = subprocess.run(
            ["osascript", "-e", script],
            capture_output=True,
            text=True,
            timeout=170,
        )
    except subprocess.TimeoutExpired:
        fail(notch_t("err_timeout"))
    if r.returncode != 0:
        err = (r.stderr or "").strip()
        if "-1743" in err or "not authorized" in err.lower():
            fail(notch_t("err_automation"))
        fail(err or notch_t("err_pick"))
    return (r.stdout or "").rstrip("\n")


def output_dir():
    custom = param("save_dir", "").strip()
    if custom:
        folder = Path(os.path.expanduser(custom)).expanduser()
        if not folder.is_dir():
            fail(notch_t("err_no_dir").format(dir=folder))
        return folder
    env_dir = env("NOTCH_OUTPUT_DIR", "").strip()
    if env_dir:
        folder = Path(env_dir)
        if folder.is_dir():
            return folder
    desktop = Path.home() / "Desktop"
    desktop.mkdir(parents=True, exist_ok=True)
    return desktop


def save_text(text, records=None):
    name_mode = param("filename", "auto").strip().lower() or "auto"
    ext = detect_ext(text, forced_format())
    folder = output_dir()
    path = unique_path(folder, suggested_name(text, name_mode, ext), ext)
    path.write_text(text, encoding="utf-8")
    if param("reveal", "1") == "1":
        subprocess.run(["open", "-R", str(path)], check=False)
    if param("open_file", "0") == "1":
        subprocess.run(["open", str(path)], check=False)
    if records is None:
        records = read_cache() or build_records()
    notch_result(
        summary=notch_t("saved").format(name=path.name),
        details=str(path),
        outputs=str(path),
        widget=widget_state(records, saved=path.name),
    )


def lookup_text(ident, records):
    for row in records:
        if row["id"] == ident:
            return row["text"]
    return None


def pick_from(records):
    if not records:
        fail(notch_t("empty"))
    if len(records) == 1:
        save_text(records[0]["text"], records)
        return
    labels = []
    mapping = {}
    used = set()
    for row in records:
        label = f"{row['ext']}  {preview_text(row['text'])}"
        base = label
        n = 2
        while label in used:
            label = f"{base} ·{n}"
            n += 1
        used.add(label)
        labels.append(label)
        mapping[label] = row["text"]
    chosen = choose_item(labels)
    if chosen in ("__CANCEL__", ""):
        notch_result(
            summary=notch_t("cancelled"),
            widget=widget_state(records, message="cancelled"),
        )
        return
    text = mapping.get(chosen)
    if text is None:
        fail(notch_t("err_not_found"))
    save_text(text, records)


def emit_list(records):
    if env("NOTCH_WIDGET_VISIBLE") or env("NOTCH_WIDGET_EVENT"):
        notch_result(widget=widget_state(records))
        return
    if not records:
        fail(notch_t("empty"))
    pick_from(records)


def payload_json():
    raw = env("NOTCH_WIDGET_PAYLOAD", "").strip()
    if not raw:
        return {}
    try:
        data = json.loads(raw)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def main():
    event = env("NOTCH_WIDGET_EVENT", "").strip()
    payload = payload_json()
    records = build_records() if event in ("", "refresh", "trigger", "pick", "save_latest") else (read_cache() or build_records())

    if event in ("refresh", "trigger"):
        notch_result(widget=widget_state(records))
        return

    if event == "save":
        ident = payload.get("id")
        if not isinstance(ident, str) or not ident:
            fail(notch_t("err_no_item"))
        text = lookup_text(ident, records)
        if text is None:
            records = build_records()
            text = lookup_text(ident, records)
        if text is None:
            fail(notch_t("err_gone"))
        save_text(text, records)
        return

    if event == "save_latest":
        if not records:
            fail(notch_t("empty"))
        save_text(records[0]["text"], records)
        return

    if event == "pick":
        pick_from(records)
        return

    emit_list(records)


if __name__ == "__main__":
    main()

