const t = k => (window.__notchWidget.i18n || {})[k] ?? k;
const titleEl = document.getElementById('title');
const countEl = document.getElementById('count');
const listEl = document.getElementById('list');
const dialogEl = document.getElementById('dialog');
const emptyEl = document.getElementById('empty');
const emptyText = document.getElementById('emptyText');
const previewEl = document.getElementById('preview');
const dialogBadge = document.getElementById('dialogBadge');
const dialogWhen = document.getElementById('dialogWhen');
const pickBtn = document.getElementById('pick');
const latestBtn = document.getElementById('latest');
const toastEl = document.getElementById('toast');
titleEl.textContent = t('title');
pickBtn.textContent = t('pick');
emptyText.textContent = t('empty_ui');
latestBtn.title = t('save_latest');
latestBtn.setAttribute('aria-label', t('save_latest'));

function uiOf(state) {
  const fromState = state && state.ui;
  const fromParams = (window.__notchWidget.params || {}).ui;
  const raw = fromState || fromParams || 'list';
  if (raw === 'dialog' || raw === '弹窗' || raw === 'button' || raw === 'picker') return 'dialog';
  return 'list';
}

function extClass(ext) {
  const key = String(ext || 'txt').toLowerCase();
  return ['md', 'json', 'html', 'xml', 'csv', 'txt'].includes(key) ? key : 'txt';
}

function badge(ext) {
  const span = document.createElement('span');
  const kind = extClass(ext);
  span.className = 'badge ' + kind;
  span.textContent = kind;
  return span;
}

function whenEl(text) {
  const span = document.createElement('span');
  span.className = 'when';
  span.textContent = text || '';
  return span;
}

function render(result) {
  if (!result || !result.ok || !result.state) return false;
  const state = result.state;
  const ui = uiOf(state);
  const items = Array.isArray(state.items) ? state.items : [];
  const empty = !items.length;
  emptyEl.hidden = !empty;
  listEl.hidden = empty || ui !== 'list';
  dialogEl.hidden = empty || ui !== 'dialog';
  latestBtn.hidden = empty;
  countEl.textContent = empty ? '' : String(items.length);
  if (empty) return true;
  if (ui === 'dialog') {
    const latest = state.latest || items[0];
    const kind = extClass(latest && latest.ext);
    dialogBadge.className = 'badge ' + kind;
    dialogBadge.textContent = kind;
    dialogWhen.textContent = (latest && latest.when) || '';
    previewEl.textContent = (latest && latest.preview) || '';
  } else {
    listEl.replaceChildren(...items.map((item, index) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = index === 0 ? 'item featured' : 'item';
      btn.title = item.preview || '';
      const preview = Object.assign(document.createElement('span'), {
        className: 'preview-line',
        textContent: item.preview || ''
      });
      const body = document.createElement('span');
      body.className = 'item-body';
      body.append(preview, whenEl(item.when));
      btn.append(badge(item.ext), body);
      btn.addEventListener('click', () => saveItem(item.id));
      return btn;
    }));
  }
  if (state.saved) showToast(t('saved_short').replace('{name}', state.saved));
  return true;
}

function showToast(text) {
  toastEl.textContent = text;
  toastEl.hidden = false;
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => { toastEl.hidden = true; }, 1800);
}

async function refresh() {
  const result = await notchany.invoke('refresh', null);
  if (!render(result) && !notchany.state) emptyEl.hidden = false;
}

async function saveItem(id) {
  const result = await notchany.execute('save', { id });
  render(result);
}

async function saveLatest() {
  const result = await notchany.execute('save_latest', null);
  render(result);
}

async function pickHistory() {
  const result = await notchany.execute('pick', null);
  render(result);
}

latestBtn.addEventListener('click', saveLatest);
pickBtn.addEventListener('click', pickHistory);

let timer;
notchany.addEventListener('visibilitychange', () => {
  clearInterval(timer);
  if (notchany.visible) {
    refresh();
    timer = setInterval(refresh, 2500);
  }
});
notchany.addEventListener('statechange', event => render(event.state));
if (notchany.state) render(notchany.state);
if (notchany.visible) {
  refresh();
  timer = setInterval(refresh, 2500);
}
